<?php
declare(strict_types=1);
namespace Morshed\Product;
use Morshed\Core\{Database,Security,Audit,Problem};
final class ContentAssets
{
    public function __construct(private Database $db,private Audit $audit){}
    private function directory():string
    {$base=__DIR__.'/../../storage/content-files';if(!is_dir($base)&&!mkdir($base,0700,true)&&!is_dir($base)){throw new Problem('STORAGE_UNAVAILABLE','فضای فایل در دسترس نیست.',503);}return realpath($base);}
    public function upload(array $a,array $file,bool $avatar=false,bool $branding=false,bool $personal=false,bool $classification=false,bool $logo=false):string
    {
        if($personal){$this->avatarStorage();}
        if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_string($file['tmp_name']??null)||!is_uploaded_file($file['tmp_name'])||!is_string($file['name']??null)){throw new Problem('INVALID_FILE','بارگذاری انجام نشد؛ فایل را دوباره انتخاب کنید.');}$meta=PrivateFiles::inspect($file['tmp_name'],$file['name']);if(($avatar||$branding)&&!$classification&&!in_array($meta['mime'],$logo?['image/png','image/jpeg','image/webp']:['image/png','image/jpeg'],true)){throw new Problem('INVALID_FILE','عکس پروفایل فقط PNG یا JPEG است.');}if($classification){$size=@getimagesize($file['tmp_name']);if(!in_array($meta['mime'],['image/png','image/webp'],true)||!$size||$size[0]!==$size[1]||$size[0]>1024||$meta['size']>1048576){throw new Problem('INVALID_FILE','آیکون باید PNG یا WebP مربع، حداکثر ۱۰۲۴ پیکسل و یک مگابایت باشد.');}}$target=null;
        try{return $this->db->tx(function()use($a,$file,$meta,$avatar,$branding,$personal,$classification,$logo,&$target){$this->db->one('SELECT id FROM m_installation WHERE id=1 FOR UPDATE');$m=null;if($classification){(new Policy($this->db))->admin($a);}elseif($branding){(new Policy($this->db))->admin($a,true);}elseif($personal){(new Policy($this->db))->user($a);}else{$m=(new Policy($this->db))->mentor($a,true);}$existing=$this->db->one('SELECT id FROM m_content_assets WHERE owner_id=? AND sha256=?',[$a['user_id'],$meta['sha256']]);if($existing){if($personal){$this->setAvatar($a['user_id'],$existing['id']);}if($avatar&&!$branding&&!$personal){$this->db->run("UPDATE m_mentors SET avatar_asset_id=?,status='review',updated_at=? WHERE user_id=?",[$existing['id'],time(),$a['user_id']]);$this->audit->add($a['user_id'],'site','mentor.portrait_review_requested',$existing['id']);}return $existing['id'];}if((int)$this->db->run('SELECT COALESCE(SUM(byte_size),0) FROM m_content_assets WHERE owner_id=?',[$a['user_id']])->fetchColumn()+$meta['size']>104857600){throw new Problem('STORAGE_LIMIT','سقف صد مگابایت فایل محتوایی تکمیل است.');}
            $key=bin2hex(random_bytes(32));$target=$this->directory().DIRECTORY_SEPARATOR.$key;if(!move_uploaded_file($file['tmp_name'],$target)){throw new Problem('STORAGE_UNAVAILABLE','ذخیره فایل انجام نشد.',503);}chmod($target,0600);if($logo){$png=$target.'.png';try{LogoImage::normalize($target,$png);if(!rename($png,$target))throw new Problem('STORAGE_UNAVAILABLE','ذخیره لوگو انجام نشد.',503);}finally{if(is_file($png))unlink($png);}$meta=['name'=>pathinfo($meta['name'],PATHINFO_FILENAME).'.png','mime'=>'image/png','size'=>filesize($target),'sha256'=>hash_file('sha256',$target)];}$id=Security::id();$this->db->run('INSERT INTO m_content_assets VALUES(?,?,?,?,?,?,?,?)',[$id,$a['user_id'],$key,$meta['name'],$meta['mime'],$meta['size'],$meta['sha256'],time()]);if($personal){$this->setAvatar($a['user_id'],$id);}if($avatar&&!$branding&&!$personal){$this->db->run("UPDATE m_mentors SET avatar_asset_id=?,status='review',updated_at=? WHERE user_id=?",[$id,time(),$a['user_id']]);}$this->audit->add($a['user_id'],'site',$branding?'branding.image_uploaded':($personal?'account.avatar_uploaded':($avatar?'mentor.portrait_review_requested':'experience.evidence_uploaded')),$id);return $id;});}catch(\Throwable $e){if($target!==null&&is_file($target)){unlink($target);}throw $e;}
    }
    private function avatarStorage():void
    {
        if($this->db->featureReady('avatars16')){return;}
        try{$this->db->run('SELECT user_id FROM m_user_avatars LIMIT 0');}catch(\PDOException $e){
            if((int)($e->errorInfo[1]??0)!==1146||$this->db->pdo->inTransaction()){throw $e;}
            $this->db->run('CREATE TABLE IF NOT EXISTS m_user_avatars (user_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,asset_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,FOREIGN KEY(user_id) REFERENCES m_users(id),FOREIGN KEY(asset_id) REFERENCES m_content_assets(id)) ENGINE=InnoDB');
        }$this->db->markFeatureReady('avatars16');
    }
    private function setAvatar(string $uid,string $id):void
    {$this->db->run('INSERT INTO m_user_avatars(user_id,asset_id) VALUES(?,?) ON DUPLICATE KEY UPDATE asset_id=VALUES(asset_id)',[$uid,$id]);}
    public function avatar(string $uid):?string
    {$this->avatarStorage();$id=$this->db->run('SELECT COALESCE(a.asset_id,m.avatar_asset_id) FROM m_users u LEFT JOIN m_user_avatars a ON a.user_id=u.id LEFT JOIN m_mentors m ON m.user_id=u.id WHERE u.id=?',[$uid])->fetchColumn();return $id?:null;}
    public function removeAvatar(array $a):void
    {$uid=(new Policy($this->db))->user($a);$this->avatarStorage();$this->db->run('DELETE FROM m_user_avatars WHERE user_id=?',[$uid]);$this->audit->add($uid,'site','account.avatar_removed',$uid);}
    public function owned(string $uid):array{return $this->db->all('SELECT id,display_name,media_type FROM m_content_assets WHERE owner_id=? ORDER BY created_at DESC LIMIT 100',[$uid]);}
    public function download(?array $a,string $id):array
    {
        (new ClassificationDetails($this->db))->storage();$f=$this->db->one('SELECT * FROM m_content_assets WHERE id=?',[$id]);if(!$f){throw new Problem('NOT_FOUND','فایل پیدا نشد.',404);}
        if(!$a&&!in_array($f['media_type'],['image/png','image/jpeg','image/webp'],true)&&$this->db->one('SELECT a.version_id FROM m_experience_assets a JOIN m_experiences e ON e.public_version_id=a.version_id WHERE a.asset_id=? LIMIT 1',[$id])){throw new Problem('MEMBERSHIP_REQUIRED','برای دریافت پیوست تجربه، وارد حساب شوید.',401);}$public=$this->db->one("SELECT m.user_id FROM m_mentors m JOIN m_users u ON u.id=m.user_id WHERE m.status='active' AND u.status='active' AND (m.avatar_asset_id=? OR EXISTS(SELECT 1 FROM m_experiences e JOIN m_experience_assets ea ON ea.version_id=e.public_version_id WHERE e.mentor_id=m.user_id AND ea.asset_id=?))",[$id,$id]);
        (new Contributions($this->db))->storage();if(!$public){$public=$this->db->one('SELECT d.org_id FROM m_organization_details d JOIN m_organization_profiles p ON p.org_id=d.org_id JOIN m_organizations o ON o.id=d.org_id AND o.active=1 WHERE d.logo_asset_id=? AND p.verified_at IS NOT NULL AND p.merged_into IS NULL',[$id]);}
        if(!$public){$public=$this->db->one('SELECT t.id FROM m_term_metadata md JOIN m_terms t ON t.id=md.term_id AND t.active=1 WHERE md.icon_asset_id=?',[$id]);}
        if(!$public){$public=$this->db->one("SELECT setting_key FROM m_public_settings WHERE setting_key IN ('footer_logo_asset','enamad_asset') AND setting_value=?",[$id]);}if(!$public){if(!$a){throw new Problem('NOT_FOUND','فایل منتشر نشده است.',404);}if(($a['realm']??'')==='admin'){(new Policy($this->db))->admin($a);$this->audit->add($a['user_id'],'admin','content.asset_reviewed',$id);}else{(new Policy($this->db))->user($a);if($a['user_id']!==$f['owner_id']){throw new Problem('NOT_FOUND','فایل در دسترس نیست.',404);}}}
        if(!preg_match('/^[a-f0-9]{64}$/D',$f['storage_key'])){throw new \RuntimeException('Invalid content storage key.');}$base=$this->directory();$path=$base.DIRECTORY_SEPARATOR.$f['storage_key'];if(is_link($path)||!is_file($path)||dirname(realpath($path))!==$base||filesize($path)!==(int)$f['byte_size']||!hash_equals($f['sha256'],hash_file('sha256',$path))){throw new Problem('STORAGE_UNAVAILABLE','یکپارچگی فایل تأیید نشد.',503);}$isLogo=$this->db->one('SELECT org_id FROM m_organization_details WHERE logo_asset_id=? LIMIT 1',[$id]);if($isLogo&&function_exists('imagecreatetruecolor')){try{$derived=$base.DIRECTORY_SEPARATOR.'logo256-'.$f['sha256'].'.png';if(!is_file($derived)){$temp=$derived.'.'.bin2hex(random_bytes(6));try{LogoImage::normalize($path,$temp);if(!rename($temp,$derived))throw new Problem('STORAGE_UNAVAILABLE','ذخیره لوگو انجام نشد.',503);}finally{if(is_file($temp))unlink($temp);}}$f['media_type']='image/png';$f['display_name']=pathinfo($f['display_name'],PATHINFO_FILENAME).'.png';$f['byte_size']=filesize($derived);$f['sha256']=hash_file('sha256',$derived);$path=$derived;}catch(Problem $e){if(!in_array($e->errorCode,['INVALID_FILE','IMAGE_MEMORY_LIMIT','IMAGE_PROCESSOR_REQUIRED'],true))throw $e;/* Keep verified legacy images readable if the host cannot build a derivative. */}}return $f+['path'=>$path];
    }
}
